<template><div class="top-bar"><div class="top-bar-left"><h3 class="top-bar-title">界面配置</h3><span class="top-bar-subtitle" v-if="activeScheme">{{activeScheme.name}} · {{lastSaveTime||'未保存'}}</span></div><div class="top-bar-right"><el-select :value="activeScheme?.id" size="small" placeholder="切换方案" style="width:160px;margin-right:12px" @change="handleSwitch"><el-option v-for="s in schemes" :key="s.id" :label="s.name" :value="s.id" /></el-select><el-button type="primary" size="small" :loading="saving" @click="$emit('save')">保存</el-button><el-button size="small" title="恢复默认" @click="$emit('reset')"><i class="el-icon-refresh-left" /></el-button><el-button size="small" title="导出配置" @click="$emit('export')"><i class="el-icon-download" /></el-button></div></div></template>
<script>export default{name:'TopBar',props:{activeScheme:{type:Object,default:null},schemes:{type:Array,default:()=>[]},saving:{type:Boolean,default:false},lastSaveTime:{type:String,default:''}},emits:['save','reset','export','switch-scheme'],methods:{handleSwitch(v){this.$emit('switch-scheme',v)}}}</script>
<style scoped>.top-bar{height:56px;display:flex;align-items:center;justify-content:space-between;padding:0 24px;background:#fff;border-bottom:1px solid #EBEEF5;flex-shrink:0}.top-bar-left{display:flex;align-items:baseline;gap:12px}.top-bar-title{margin:0;font-size:18px;font-weight:700;color:#0f172a}.top-bar-subtitle{font-size:13px;color:#94a3b8}.top-bar-right{display:flex;align-items:center;gap:8px}</style>
